import numpy as np
L=open('init2.xyz').read().split('\n')[2:]
sy=[];p=[]
for l in L:
    if l.strip():
        t=l.split(); sy.append(t[0]); p.append([float(x) for x in t[1:4]])
p=np.array(p); d=np.linalg.norm(p[:,None]-p[None],axis=2); np.fill_diagonal(d,9)
for i,j in np.argwhere(d<2.0):
    if i<j: print(i,sy[i],j,sy[j],round(d[i,j],2))
"
